// 生成は「方向ごとに基準の体1枚」だけ（OpenAI）。歩行2・攻撃はその基準を
// .scratch/grid-tool.mjs で 32×32 グリッド編集して作る（SPRITE-PIPELINE.md §6）。
// スケールは .scratch/quantize-shared.mjs --height 28（身長を28行に正規化＝向きを変えても背が
// 変わらない）。3方向すべて rows 4-31（28行）で一致。
// 剣は常に「個体の右前脚」＝DOWN では画面左・RIGHT では前方・UP（背面視）では画面右に出る。
// 刃のシルエットは全方向で共通（幅3＝明鋼2列＋影1列／鍔は幅5）＝同じ剣に見せるため
// （ENEMY-DIRECTIONAL-GUIDE.md §6-2）。攻撃は「向いている方向へ刃をフレーム端まで突き出す」
// ＝DOWN は下端／RIGHT は右端／UP は上端。歩行2は前脚1本を2行浮かせる（差分 16/17/27 ドット）。
// ガードポーズは無い＝ENEMY_META.guards:false（高機動の敵が立ち止まって構えるのは設計と矛盾）
// ∴ ${base}${Dir}Guard は要らない（skeleton は 3方向×3ポーズ＝12枚）。
