// ── k-3 の3体（地中蟲・跳躍蜘蛛・コウモリ・Phase 5.5k #1/#2/#9）── 32×32・歩行2フレーム ──
// 3体とも ENEMY_META.directional を持たない＝向き別の通常/攻撃/構えの9枚は要らない
// （ENEMY-DIRECTIONAL-GUIDE.md §2 の命名規則は directional な敵だけの要件）。
// ∴ 1エントリに歩行2枚を入れる（shared/sprites.js が animFrame % frames.length で交互に出す）。
// 生成したのは各体1枚だけで、歩行2はそのグリッドを編集して作った（SPRITE-PIPELINE.md §3-1 ★★
// ＝ポーズを生成し直すと体格が変わり、400ms 交替では「ズーム」に見える）：
//   地中蟲   … 節の境界3本を1行ずらす蠕動（脚で歩く生き物ではない・輪郭と身長は不変）
//   跳躍蜘蛛 … 胴（x9-22）を固定し左脚群を1行下・右脚群を1行上（.scratch/shift-spider-legs.mjs）
//   コウモリ … 2枚は「翼を上げた／下げた」＝羽ばたき（下記のとおり生成物ではなく手描き）
// ⚠️ コウモリだけ生成画像を使わず 32×32 グリッドに手で描いた（.scratch/draw-bat.mjs・行スパン）。
// 理由（ユーザー指摘 2026-08-14 の2件）：
//   ① セルいっぱいだと「巨大蝙蝠」に見える＝ξ は「小さいが多数で変則軌道だから厄介」な敵
//      ∴ 22×13 に収め、グリッド寸法は 32×32 のままにする（drawSprite は cols×rows の canvas を
//      CSS で伸ばす∴外周の透明がそのまま「小ささ」になる）。
//   ② 生成物の翼を潰す/ずらすだけでは羽ばたきに見えない。さらに生成物は胴が翼より大きく、
//      翼を下げると「脚が生えた虫」に見えた∴コウモリは「大きい翼＋小さい胴」で描く。
//      翼は腕（外側の縁）と胴の間を膜で埋めた三角形＝細い帯だと触角/脚に見える。
//      2枚は row15（肩）を軸に上下反転した形＝上げた翼と下げた翼。
// 視点は ENEMY_META のフラグから導いた（ENEMY-DIRECTIONAL-GUIDE.md §6-3＝絵の根拠はエンジン実装）：
//   batSwarm は sideView:true ∴横向き（素の向きは右・player.x < e.x で反転＝game/render-chars.js）
//   生成物は眼が左＝左向きだったので左右反転をピクセルに焼いてから登録している
//   （batSwarm という名前だが絵は「コウモリ1匹」。大量のコウモリはステージ配置で表す）
//   burrowWorm / leapSpider は sideView なし＝反転されない∴向きに依らない姿（正面/真上）で描く。
// 隠れ・滞空の見た目はスプライトではなく CSS が描く（game/css/board.css の .hiding ＋
// hide-burrow / hide-air）∴「潜っている姿」「滞空の影」の絵は持たない＝実体化した姿だけでよい。
