// ── k-4 の2体（盾騎士・火吐き亀・Phase 5.5k #4/#12）── 32×32 ──────────────
// 盾騎士（ζ）＝directional かつ guards:false ∴必要なのは D/R/U と DAtk/RAtk/UAtk の6エントリ
// （Guard の3枚は要らない＝ENEMY-DIRECTIONAL-GUIDE.md §1/§2。left は R をピクセルに焼いた反転で出る）。
// 生成したのは基準ボディ2枚（DOWN と UP）だけで、残りはそのグリッドを編集して作った
// （SPRITE-PIPELINE.md §3-1 ★★＝ポーズを生成し直すと体格が変わり 400ms 交替で「ズーム」に見える）：
//   D  … 生成した正面ボディ。盾の面だけを青へ寄せた／歩行2は画面左の脚を2行浮かせる
//   DAtk … 上げていた剣を消し、鍔＋幅2の刃を体の手前（フレーム下端）へ突き出す
//   R  … ★横向きは生成できない（3回引いて3回とも塊になった）∴DOWN のボディから構築した。
//         根拠はエンジン実装（§6-3）＝shared/sprites-player.js の heroR は「細身のプロフィール」
//         ではなく正面ボディのままで、向きは顔の要素の寄せ方と盾/剣のオーバーレイで示している
//         （game/render-chars.js の待機時＝right/left は shieldSide＝細い側面帯）。
//         ∴騎士も胴体は DOWN と同一シルエットのまま、①覗き穴を右端へ寄せ②盾を右端の側面バンドに
//         し③剣を背側（画面左）へ回す、の3点だけで「画面右を向いている」を出す。
//   RAtk … 背側の剣を画面右へ水平に振る（盾のバンド row15 より上の高さに置いて重ならない）
//   U  … 生成した背面ボディ。背面視は持ち手が左右入れ替わる∴剣は画面左・盾は画面右。
//         盾は**体より奥**（render-chars.js は up だけ z-index -1）∴透明セルだけを盾色にして
//         体を手前に残す（fill だと鎧を塗り潰して盾が手前になる＝§6-2 の重なりの規則）。
//         形は DOWN の凧形を体の中心で鏡像にしたもの＝同じ盾のシルエットを崩さない。
//   UAtk … 刃を奥（フレーム上端）まで伸ばす
// 火吐き亀（φ）＝directional も sideView も持たない∴向きに依らない「真上から見た姿」1系統。
// 開（歩行2枚）と閉（甲羅だけ1枚）の2エントリで、**甲羅の開閉は meta.shell の無敵窓と対応する**
// ＝籠もり中は向きを問わず全ダメージ 0 なので、プレイヤーは絵から「今は殴っても弾かれる」を
// 読む（§6-1＝ポーズが見分けられなければ機構が伝わらないのと同じ）。∴閉は頭・尾・4脚を消して
// 甲羅だけにし（不透明 30行→17行・差分 430ドット）、甲羅だけだと上に浮くので4行下げてある。
