// ── k-5 の2体（分裂スライム・ルピー喰い・Phase 5.5k #3/#11）── 32×32 ──────────
// どちらも directional でも sideView でもない∴向きに依らない1系統（反転もされない）。
// 生成したのは基準ボディ2枚（親スライム・ルピー喰い）だけで、残り4枚はそのグリッドから
// 構築した（SPRITE-PIPELINE.md §3-1 ★★＝ポーズを生成し直すと体格が変わり、400ms 交替の
// 歩行アニメでは「ズーム」に見える。.scratch/build-k5-frames.mjs）：
//   splitSlime      … 生成した親のドーム。歩行2は 2行つぶして「跳ねて着地した瞬間」にし、
//                     照り返しを1列右へずらす（ゼリーの揺れ）＝差分 165ドット。
//   splitSlimeSmall … 親を 0.55 に縮小して接地（親 28行 → 小型 15行）。**親と一目で別物である
//                     ことが分裂の機構そのもの**＝プレイヤーは「増えた」を絵で読む（§6-1）。
//                     ⚠️ 眼は縮小では残らない（§3-1 ★）∴縮小後に 2×2 で描き直し、潰れた眼の
//                     残骸（胴の内側に散る暗色）は先に消す（残すと歪んだ塊に見える）。
//                     グリッドは 32×32 のまま＝外周の透明が「小ささ」になる（drawSprite は
//                     配列のドット数を内部解像度に採るだけ・表示サイズは CSS 固定）。
