// ── k-6 の2体（爆弾鬼・ブーメラン鬼・Phase 5.5k #6/#10）── 32×32 ──────────────
// どちらも directional かつ guards:false ∴必要なのは D/R/U と DAtk/RAtk/UAtk の6エントリ
// （Guard の3枚は要らない＝ENEMY-DIRECTIONAL-GUIDE.md §1/§2。left は R をピクセルに焼いた反転で出る）。
// 生成したのは基準ボディ DOWN 1枚ずつだけで、残りは全てそのグリッド編集で作った
// （SPRITE-PIPELINE.md §3-1 ★★＝ポーズを生成し直すと体格が変わり 400ms 交替で「ズーム」に見える）：
//   R  … ★横向きは生成できない（k-4b 盾騎士の結論）∴顔の造作を進行方向へ寄せ（眼・鼻・口・牙は
//         全部残す＝消して描き直すと無地の塊になる）、奥の腕を肘まで引いて作った。
//   U  … ★背面視も生成できなかった（2体とも試して破綻＝爆弾鬼は全面グロー＋輪郭消失／
//         ブーメラン鬼は黒縁が入り体格も DOWN と揃わなかった）∴**完成した DOWN を flipx して
//         顔だけ後頭部に描き替えた**。flipx は §6-2 の「背面視は持ち手が左右入れ替わる」を自動で
//         満たし、シルエット・持ち物の形・脚の運びが DOWN の厳密な鏡像になる。
//         後頭部は頭頂・側頭部・襟足の縁取りだけ（縦の中心線を入れると「樽」に見えた）。
// ★ 持ち物の絵は実際に飛んでくる投擲物から取った（§6-3＝絵の根拠は実装から）＝爆弾は
//   ITEM_SPRITES.thrownBomb の黒球（導火線＋火花まで描く）／ブーメランは ITEM_SPRITES.boomerang の
//   木色の L 字。**1セル≒1.5画面px** しか無いので線は3セル以上で組む（item の 8×8 をそのまま
//   移植すると潰れて「タンの塊」に見えた）。
// ★★ 攻撃ポーズは2体で別の形にした＝**飛び方（k-6a で実装した flight style）の写し**：
//   爆弾鬼     … lob＝放物線で壁を越える  ∴玉を**頭より上へ振り上げる**（下手投げでは越えない）
//   ブーメラン鬼 … 水平に直進して戻る      ∴腕を**体の前へ振り抜く**（DOWN）／**前へ伸ばし切る**（R）
// これで「剣を振る敵」（骸骨剣士・剣獣・盾騎士＝刃が伸びる）とも、2体同士とも混同しない
// ＝プレイヤーは間合いの取り方を絵から選べる（§6-1）。
