// ── k-7 の2体（呪い火・毒沼ヒル・Phase 5.5k #13/#15）── 32×32 ──────────────
// どちらも directional:false・guards:false ∴必要なのは1名につき1エントリ（2フレーム）だけ。
// sideView も持たない∴向きに依らない姿で描く（地中蟲・跳躍蜘蛛と同じ作法）。
// ★ 2体とも生成 API を使わず手で組んだ（.scratch/draw-k7.mjs）＝SPRITE-PIPELINE.md §3-1 ★★
//   「動きが本質の敵は最初から手描き」。呪い火は炎の揺らぎ・毒沼ヒルは体の伸縮が2フレームの中身
//   ∴生成物を加工する道では2枚目が作れない。炎は生成が全面グローになる既知の失敗もある（同 ★）。
// ★ 絵は機構を名指す（ENEMY-DIRECTIONAL-GUIDE.md §6-1）：
//   呪い火   … 剣を封じる敵∴**炎に飲み込まれた剣**を炎の内側に完全に収めて描く。
//              ⚠️ 柄を炎の上へ出すと金の口金＋丸い胴で「香水瓶」に見え、剣を大きく描くと金の塊が
//              「T字＝トロフィー/電気スタンド」に見えた∴剣は小さく（刃3幅・鍔7幅＝骸骨剣士の
//              攻撃フレームと同じ寸法比）、輪郭に金属を出さない。
//   毒沼ヒル … 毒を持つヒル∴**背を貫く黄緑の縞＋毒色の吸口**で警告する。
//              ⚠️ 毒を丸い斑点にすると 32×32 では縦につぶれて「黄緑の錠剤が並ぶ」形になり、
//              後吸盤を体より太い円盤にすると「桃色の長靴」（同心の輪では「コンセント」）に
//              見えた∴縞＋尖った尾に変えた。体は9セル幅（縞3セルを引いても両脇に赤が残る幅）。
// ★ 陰影は「外側からの距離」ではなく**中心線からの相対距離**で作る＝丸い管に見える
//   （距離層だと太い部分が一様な明色の面になり平らな塊に見えた）。炎だけは距離層が正しい
//   （＝根元が熱い＝芯を下半分に限る。上半分まで芯を出すと内部が白飛びして「風船」になる）。
// ★ 2フレームの差＝呪い火 38ドット／毒沼ヒル 98ドット（歩行の下限 17ドット・§6 の数え方）。
//   毒沼ヒルは頭を3行引き寄せて縮ませ、**尾の3行は両フレームで同一**＝尾で地面を掴んだまま
//   体だけが伸縮して見える（下端が動くと「背が伸び縮み」に見える＝§3-1 ★の接地の話と同型）。
// ── Phase 5.5k k-8a: 術士（瞬間移動）のパレット ──────────────────────────
// ⚠️ 石床（明部 #3a3848＝相対輝度 57.6）より暗い色で塗ると床に沈んで見えない
//    （k-4〜k-6 で実際に起きた欠陥）∴縁以外は床より明るい色で組む。
//    輝度＝37.6/69.9/102.5/162.8/222.5（床より暗いのは 1＝縁だけ）。
// 1=縁/頭巾の奥 2=衣の陰 3=衣の面 4=衣の明部・手 5=金（宝珠/眼/呪符＝`.hide-warp` と同色）
ENEMY_PAL.sorcerer = ['transparent','#2a2050','#4a3ab0','#6a5ad8','#a898ff','#ffe070'];
// ── k-8 の術士（sorcerer・Phase 5.5k #5）── 32×32 ────────────────────────
// directional:false・sideView なし・speed 0 ∴向きに依らない姿1組で足りる
// （待機2フレーム＝宝珠の脈動／詠唱1フレーム＝enemy-ai.js の syncCastSprite が差し替える）。
// ★ 生成 API を使わず手で組んだ（.scratch/draw-k8.mjs）＝SPRITE-PIPELINE.md §3-1 ★★。
//   ① パレットは k-8a で確定済み（藍＋金・tests/blink-enemy.spec.js ② が輝度を固定）∴
//      量子化で作り直すとパレットが動きテストの前提が壊れる。
//   ② 詠唱ポーズは「腕を輪郭の外へ出す」ことが要件＝プロンプトでは押し切れない指定。
// ★ 絵が名指す機構（ENEMY-DIRECTIONAL-GUIDE.md §6-1）：
//   ・尖った頭巾＋裾で脚が見えない … speed 0＝歩かない敵（歩行フレームを持たない理由）
//   ・杖＋金の宝珠＋胸の呪符       … 詠唱者＝殴りに行く相手（遠隔兵 F と見分ける）
//   ・金は `.hide-warp` の金の輪と同色 … 消えて転移する敵だと読める（k-8b 合格条件2）
//   ・詠唱は腕を輪郭の外へ挙げ宝珠が一段燃える … 出現→3 tick 後に魔弾が来る予告
// ★ 捨てた案（すべて自分で描画を見て潰した。1セル≒1.5画面px の読み違い＝§3-1 ★★）：
//   ・柄を5セル幅にすると宝珠との太さの差が消え「街灯／棒付きキャンディ」
//   ・袖を水平の帯で架けると金の縦棒を横棒が貫き「十字の標識」∴袖は斜めに落とす
//   ・待機にも右手を出すと左の袖と対になって腕2本が水平に貫く絵になる∴右腕は詠唱だけ
//   ・頭巾の空洞を矩形にすると暗い帯＋金の四角2つで「サングラス」∴六角形の穴
//   ・裾に縦のひだを入れると裾から脚2本が出て見える（歩かない敵と逆の絵）∴裾は割らない
//   ・宝珠の光条（1セルの斜線）は実機で消える∴輪と芯を太らせて脈動させる
//   ・宝珠の芯を輪の内側いっぱいに広げると金が輪郭線になり「虫眼鏡／手鏡」∴芯は2セル以上小さく
// ★ フレーム差＝待機1↔待機2 が 27ドット（歩行/脈動の下限 17）・待機↔詠唱が 108ドット
//   （ポーズ差の下限 48・§6 の数え方）。詠唱では宝珠・眼・腕の3箇所が同時に変わる。
